<?php require_once("../Model/DatabaseConnection.php"); $db=new DatabaseConnection(); $connection=$db->openConnection(); $products=$connection->query("SELECT * FROM products ORDER BY id DESC"); require("header.php"); ?>Products</div><?php require("footer.php"); ?><div class="tablebox"><div class="toolbar"><h2>Products</h2><a class="btn" href="addProduct.php">Add Product</a></div><table class="table"><tr><th>ID</th><th>Product</th><th>Price</th><th>Stock</th><th>Category</th><th>Status</th><th>Actions</th></tr><?php while($p=$products->fetch_assoc()): ?><tr><td><?=$p['id']?></td><td><?=htmlspecialchars($p['product_name'])?></td><td>৳ <?=number_format($p['price'])?></td><td><?=$p['stock']?></td><td><?=htmlspecialchars($p['category'])?></td><td><span class="badge active"><?=htmlspecialchars($p['status'])?></span></td><td class="actions"><a class="btn secondary" href="editProduct.php?id=<?=$p['id']?>">Edit</a><a class="btn danger" onclick="return confirm('Delete this product?')" href="../Controller/productController.php?action=delete&id=<?=$p['id']?>">Delete</a></td></tr><?php endwhile; ?></table></div></main></div></body></html>
